window.WORDS = [{"term":"critical heat flux (CHF)","pronunciation":"/ˈkrɪtɪkəl hiːt flʌks/","koreanPronunciation":"크리티컬 히트 플럭스","korean":"임계열유속","meaning":"핵비등 열전달이 한계에 도달해 가열면 온도가 급격히 상승할 수 있는 최대 열유속.","category":"Boiling","example":"The critical heat flux is a key thermal limit in pool boiling.","translation":"임계열유속은 풀비등에서 핵심적인 열적 한계이다.","collocations":["CHF enhancement","CHF condition","CHF correlation","reach CHF"],"paper":"Pool-boiling literature","sourceType":"학습 예문"},{"term":"heat flux","pronunciation":"/hiːt flʌks/","koreanPronunciation":"히트 플럭스","korean":"열유속","meaning":"단위 면적당 전달되는 열전달률.","category":"Heat Transfer","example":"Heat flux was increased stepwise until the boiling crisis was observed.","translation":"비등 위기가 관찰될 때까지 열유속을 단계적으로 증가시켰다.","collocations":["increase heat flux","heat flux level","local heat flux"],"paper":"General heat-transfer literature","sourceType":"학습 예문"},{"term":"heat transfer coefficient","pronunciation":"/hiːt ˈtrænsfɜːr ˌkoʊɪˈfɪʃənt/","koreanPronunciation":"히트 트랜스퍼 코이피션트","korean":"열전달계수","meaning":"열유속을 벽면 과열도로 나눈 값으로 비등 열전달 성능을 나타내는 대표 지표.","category":"Heat Transfer","example":"The heat transfer coefficient increased after surface modification.","translation":"표면 개질 후 열전달계수가 증가하였다.","collocations":["HTC enhancement","boiling heat transfer coefficient","local HTC"],"paper":"LN2 pool-boiling literature","sourceType":"학습 예문"},{"term":"wall superheat","pronunciation":"/wɔːl ˈsuːpərhiːt/","koreanPronunciation":"월 슈퍼히트","korean":"벽면 과열도","meaning":"가열면 온도와 유체 포화온도의 차이.","category":"Boiling","example":"The wall superheat rose sharply near the boiling crisis.","translation":"비등 위기점 부근에서 벽면 과열도가 급격히 상승하였다.","collocations":["surface superheat","degree of superheat","wall temperature"],"paper":"Pool-boiling fundamentals","sourceType":"학습 예문"},{"term":"saturation temperature","pronunciation":"/ˌsætʃəˈreɪʃən ˈtemprətʃər/","koreanPronunciation":"새처레이션 템퍼러처","korean":"포화온도","meaning":"주어진 압력에서 액체와 증기가 평형을 이루는 온도.","category":"Cryogenics","example":"The saturation temperature of the liquid depends on pressure.","translation":"액체의 포화온도는 압력에 따라 달라진다.","collocations":["saturation pressure","Tsat","saturated liquid"],"paper":"Cryogenic thermodynamics","sourceType":"학습 예문"},{"term":"nucleate boiling","pronunciation":"/ˈnuːkliət ˈbɔɪlɪŋ/","koreanPronunciation":"뉴클리에이트 보일링","korean":"핵비등","meaning":"가열면의 핵생성 지점에서 기포가 생성·성장·이탈하며 높은 열전달을 보이는 비등 영역.","category":"Boiling","example":"Bubble growth and departure dominate heat transfer in nucleate boiling.","translation":"핵비등에서는 기포의 성장과 이탈이 열전달을 지배한다.","collocations":["nucleate boiling region","developed nucleate boiling","onset of nucleate boiling"],"paper":"Pool-boiling fundamentals","sourceType":"학습 예문"},{"term":"transition boiling","pronunciation":"/trænˈzɪʃən ˈbɔɪlɪŋ/","koreanPronunciation":"트랜지션 보일링","korean":"전이비등","meaning":"CHF 이후 젖음 영역과 증기막 영역이 공존하며 불안정한 열전달이 나타나는 영역.","category":"Boiling","example":"The transition from nucleate boiling to film boiling can occur rapidly.","translation":"핵비등에서 막비등으로의 전이는 빠르게 일어날 수 있다.","collocations":["transition boiling regime","post-CHF boiling","transition process"],"paper":"Transition-boiling literature","sourceType":"학습 예문"},{"term":"film boiling","pronunciation":"/fɪlm ˈbɔɪlɪŋ/","koreanPronunciation":"필름 보일링","korean":"막비등","meaning":"가열면이 연속적인 증기막으로 덮여 액체와의 직접 접촉이 크게 줄어든 상태.","category":"Boiling","example":"A continuous vapor film shields the heating surface during film boiling.","translation":"막비등에서는 연속적인 증기막이 가열면을 차폐한다.","collocations":["stable film boiling","film boiling regime","vapor film"],"paper":"Boiling-crisis literature","sourceType":"학습 예문"},{"term":"boiling crisis","pronunciation":"/ˈbɔɪlɪŋ ˈkraɪsɪs/","koreanPronunciation":"보일링 크라이시스","korean":"비등 위기","meaning":"핵비등에서 효율적 냉각이 붕괴하여 가열면 온도가 급상승하는 현상.","category":"Boiling","example":"The boiling crisis was identified from the abrupt change in heater response.","translation":"비등 위기는 가열기 응답의 급격한 변화로 식별하였다.","collocations":["boiling crisis development","critical condition","thermal crisis"],"paper":"Boiling-crisis literature","sourceType":"학습 예문"},{"term":"nucleation site","pronunciation":"/ˌnuːkliˈeɪʃən saɪt/","koreanPronunciation":"뉴클리에이션 사이트","korean":"핵생성 지점","meaning":"기포 핵이 안정적으로 생성되는 표면의 미세 공동 또는 위치.","category":"Bubble Dynamics","example":"Active nucleation sites strongly influence nucleate boiling behavior.","translation":"활성 핵생성 지점은 핵비등 거동에 큰 영향을 준다.","collocations":["active nucleation site","site density","cavity activation"],"paper":"Surface-boiling literature","sourceType":"학습 예문"},{"term":"active cavity","pronunciation":"/ˈæktɪv ˈkævəti/","koreanPronunciation":"액티브 캐비티","korean":"활성 공동","meaning":"실제 기포 핵생성을 지속적으로 유발하는 표면 미세 공동.","category":"Bubble Dynamics","example":"Only a fraction of surface cavities remain active during boiling.","translation":"표면 공동 중 일부만이 비등 중 활성 상태를 유지한다.","collocations":["cavity radius","cavity activation","active site"],"paper":"Nucleation literature","sourceType":"학습 예문"},{"term":"bubble departure","pronunciation":"/ˈbʌbəl dɪˈpɑːrtʃər/","koreanPronunciation":"버블 디파처","korean":"기포 이탈","meaning":"기포가 가열면에서 떨어져 액체 벌크로 이동하는 과정.","category":"Bubble Dynamics","example":"Improved wettability can promote bubble departure from the heating surface.","translation":"향상된 젖음성은 가열면에서 기포 이탈을 촉진할 수 있다.","collocations":["departure diameter","bubble departure frequency","promote departure"],"paper":"Bubble-dynamics literature","sourceType":"학습 예문"},{"term":"departure diameter","pronunciation":"/dɪˈpɑːrtʃər daɪˈæmɪtər/","koreanPronunciation":"디파처 다이애미터","korean":"이탈 직경","meaning":"기포가 가열면에서 이탈하는 순간의 기포 직경.","category":"Bubble Dynamics","example":"The bubble departure diameter generally changes with surface and fluid properties.","translation":"기포 이탈 직경은 일반적으로 표면 및 유체 물성에 따라 변한다.","collocations":["bubble diameter","diameter at departure","departure size"],"paper":"Bubble-dynamics literature","sourceType":"학습 예문"},{"term":"detachment frequency","pronunciation":"/dɪˈtætʃmənt ˈfriːkwənsi/","koreanPronunciation":"디태치먼트 프리퀀시","korean":"이탈 빈도","meaning":"단위시간당 기포 또는 합체 기포가 가열면에서 이탈하는 횟수.","category":"Bubble Dynamics","example":"The detachment frequency of coalesced bubbles is one of the important parameters in the boiling heat transfer model at high heat flux.","translation":"합체 기포의 이탈 빈도는 고열유속 비등 열전달 모델에서 중요한 매개변수 중 하나이다.","collocations":["bubble detachment","departure frequency","detachment behavior"],"paper":"Jin et al., Cryogenics 51 (2011) 516–520","sourceType":"논문 원문"},{"term":"coalescence","pronunciation":"/ˌkoʊəˈlesəns/","koreanPronunciation":"코얼레선스","korean":"합체","meaning":"인접한 기포들이 합쳐져 더 큰 기포나 증기 구조를 만드는 현상.","category":"Bubble Dynamics","example":"Coalescence becomes increasingly important as bubble population increases.","translation":"기포 수가 증가할수록 기포 합체의 중요성이 커진다.","collocations":["bubble coalescence","coalesced bubble","vapor coalescence"],"paper":"Jin et al., Cryogenics 51 (2011)","sourceType":"학습 예문"},{"term":"coalesced bubble","pronunciation":"/ˌkoʊəˈlest ˈbʌbəl/","koreanPronunciation":"코얼레스트 버블","korean":"합체 기포","meaning":"여러 작은 기포가 결합해 형성된 큰 기포.","category":"Bubble Dynamics","example":"The detachment frequency of coalesced bubbles decreased as heat flux increased.","translation":"열유속이 증가함에 따라 합체 기포의 이탈 빈도는 감소하였다.","collocations":["mushroom-shaped bubble","large vapor mass","bubble period"],"paper":"Jin et al., Cryogenics 51 (2011) 516–520","sourceType":"논문 기반 예문"},{"term":"macrolayer","pronunciation":"/ˈmækroʊˌleɪər/","koreanPronunciation":"매크로레이어","korean":"매크로층","meaning":"고열유속 핵비등에서 큰 합체 기포 아래에 존재한다고 보는 얇은 액체층.","category":"Bubble Dynamics","example":"The macrolayer is periodically evaporated and resupplied beneath coalesced bubbles.","translation":"매크로층은 합체 기포 아래에서 주기적으로 증발하고 다시 공급된다.","collocations":["macrolayer evaporation","liquid macrolayer","macrolayer thickness"],"paper":"Jin et al., Cryogenics 51 (2011)","sourceType":"학습 예문"},{"term":"evaporation","pronunciation":"/ɪˌvæpəˈreɪʃən/","koreanPronunciation":"이배퍼레이션","korean":"증발","meaning":"액체가 기체로 상변화하는 과정.","category":"Heat Transfer","example":"Evaporation of the liquid layer contributes directly to heat removal.","translation":"액체층의 증발은 열 제거에 직접 기여한다.","collocations":["evaporation rate","evaporation front","latent heat of evaporation"],"paper":"Heat-transfer literature","sourceType":"학습 예문"},{"term":"latent heat of evaporation","pronunciation":"/ˈleɪtənt hiːt əv ɪˌvæpəˈreɪʃən/","koreanPronunciation":"레이턴트 히트 오브 이배퍼레이션","korean":"증발 잠열","meaning":"단위 질량의 액체가 온도 변화 없이 증기로 상변화하는 데 필요한 에너지.","category":"Cryogenics","example":"Cryogenic liquids often have a small latent heat of evaporation.","translation":"극저온 액체는 대체로 증발 잠열이 작다.","collocations":["latent heat","heat of vaporization","phase change energy"],"paper":"Cryogenic thermodynamics","sourceType":"학습 예문"},{"term":"rewetting","pronunciation":"/ˌriːˈwetɪŋ/","koreanPronunciation":"리웨팅","korean":"재젖음","meaning":"증기막이나 건조 영역이 사라진 뒤 액체가 가열면과 다시 직접 접촉하는 과정.","category":"Bubble Dynamics","example":"Rapid rewetting can delay formation of a stable vapor film.","translation":"빠른 재젖음은 안정한 증기막 형성을 지연시킬 수 있다.","collocations":["surface rewetting","rewetting process","rewetting capability"],"paper":"Transition-boiling literature","sourceType":"학습 예문"},{"term":"liquid replenishment","pronunciation":"/ˈlɪkwɪd rɪˈplenɪʃmənt/","koreanPronunciation":"리퀴드 리플레니시먼트","korean":"액체 재공급","meaning":"기포 이탈이나 증발로 비워진 가열면 근처에 액체가 다시 공급되는 과정.","category":"Bubble Dynamics","example":"Capillary structures can improve liquid replenishment to hot surface regions.","translation":"모세관 구조는 고온 표면 영역으로의 액체 재공급을 개선할 수 있다.","collocations":["liquid supply","replenishment rate","wicking-assisted supply"],"paper":"Surface-enhanced boiling literature","sourceType":"학습 예문"},{"term":"dryout","pronunciation":"/ˈdraɪaʊt/","koreanPronunciation":"드라이아웃","korean":"건조","meaning":"가열면 근처의 액체가 사라져 표면이 증기로 덮이는 현상.","category":"Boiling","example":"Local dryout increases the thermal resistance between the surface and the liquid.","translation":"국부 건조는 표면과 액체 사이의 열저항을 증가시킨다.","collocations":["local dryout","dry patch","surface dryout"],"paper":"Boiling-crisis literature","sourceType":"학습 예문"},{"term":"hydrodynamic instability","pronunciation":"/ˌhaɪdroʊdaɪˈnæmɪk ˌɪnstəˈbɪləti/","koreanPronunciation":"하이드로다이내믹 인스터빌리티","korean":"유체역학적 불안정성","meaning":"액체-증기 유동 계면의 불안정성이 커져 비등 위기와 연결되는 현상.","category":"Boiling","example":"Hydrodynamic instability is frequently invoked in classical CHF models.","translation":"유체역학적 불안정성은 고전적 CHF 모델에서 자주 사용되는 개념이다.","collocations":["instability theory","vapor-liquid interface","hydrodynamic model"],"paper":"CHF modeling literature","sourceType":"학습 예문"},{"term":"cryogenic liquid","pronunciation":"/ˌkraɪəˈdʒenɪk ˈlɪkwɪd/","koreanPronunciation":"크라이어제닉 리퀴드","korean":"극저온 액체","meaning":"매우 낮은 온도에서 액체 상태를 유지하는 유체. 액체질소, 액체수소 등이 대표적이다.","category":"Cryogenics","example":"Cryogenic liquids have thermophysical properties distinct from room-temperature fluids.","translation":"극저온 액체는 상온 유체와 다른 열물성을 갖는다.","collocations":["cryogenic fluid","liquid nitrogen","cryogenic boiling"],"paper":"Cryogenics literature","sourceType":"학습 예문"},{"term":"heat leak","pronunciation":"/hiːt liːk/","koreanPronunciation":"히트 리크","korean":"열침입","meaning":"외부에서 극저온 시스템 내부로 유입되는 불필요한 열.","category":"Cryogenics","example":"Vacuum insulation is used to reduce heat leak into the liquid nitrogen vessel.","translation":"진공 단열은 액체질소 용기로의 열침입을 줄이기 위해 사용된다.","collocations":["parasitic heat leak","radiative heat leak","minimize heat leak"],"paper":"Cryogenic apparatus literature","sourceType":"학습 예문"},{"term":"subcooling","pronunciation":"/ˌsʌbˈkuːlɪŋ/","koreanPronunciation":"서브쿨링","korean":"과냉도","meaning":"액체 온도가 해당 압력의 포화온도보다 낮은 상태 또는 그 온도차.","category":"Cryogenics","example":"Greater subcooling generally delays bulk vapor generation.","translation":"과냉도가 커지면 일반적으로 벌크 증기 발생이 지연된다.","collocations":["degree of subcooling","subcooled liquid","subcooled boiling"],"paper":"Boiling literature","sourceType":"학습 예문"},{"term":"surface modification","pronunciation":"/ˈsɜːrfɪs ˌmɑːdɪfɪˈkeɪʃən/","koreanPronunciation":"서피스 모디피케이션","korean":"표면 개질","meaning":"표면의 형상, 화학성분, 젖음성 등을 의도적으로 변화시키는 처리.","category":"Surface","example":"Surface modification can alter both nucleation behavior and liquid supply.","translation":"표면 개질은 핵생성과 액체 공급 거동을 모두 변화시킬 수 있다.","collocations":["modified surface","surface treatment","surface engineering"],"paper":"Surface-boiling literature","sourceType":"학습 예문"},{"term":"electropolishing","pronunciation":"/ɪˌlektroʊˈpɑːlɪʃɪŋ/","koreanPronunciation":"일렉트로폴리싱","korean":"전해연마","meaning":"전기화학적 용해를 이용해 표면 미세 돌기와 거칠기를 줄이는 공정.","category":"Surface","example":"Electropolishing is commonly used to obtain a smoother metallic surface.","translation":"전해연마는 더 평활한 금속 표면을 얻기 위해 흔히 사용된다.","collocations":["electropolished surface","electrolyte","current density"],"paper":"Surface-processing literature","sourceType":"학습 예문"},{"term":"anodic oxidation","pronunciation":"/əˈnɑːdɪk ˌɑːksɪˈdeɪʃən/","koreanPronunciation":"어노딕 옥시데이션","korean":"양극산화","meaning":"시편을 양극으로 사용해 표면에 산화물 또는 수산화물 구조를 형성하는 전기화학 공정.","category":"Surface","example":"Anodic oxidation can create micro- or nanostructures on a metal surface.","translation":"양극산화는 금속 표면에 마이크로 또는 나노 구조를 형성할 수 있다.","collocations":["anodized surface","oxide layer","electrochemical oxidation"],"paper":"Surface-processing literature","sourceType":"학습 예문"},{"term":"surface roughness","pronunciation":"/ˈsɜːrfɪs ˈrʌfnəs/","koreanPronunciation":"서피스 러프니스","korean":"표면 거칠기","meaning":"표면 높이 변동의 정도를 나타내는 형상학적 특성.","category":"Surface","example":"Surface roughness can influence the number and stability of active nucleation sites.","translation":"표면 거칠기는 활성 핵생성 지점의 수와 안정성에 영향을 줄 수 있다.","collocations":["roughness parameter","Ra","surface topography"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007)","sourceType":"학습 예문"},{"term":"contact angle","pronunciation":"/ˈkɑːntækt ˈæŋɡəl/","koreanPronunciation":"콘택트 앵글","korean":"접촉각","meaning":"고체-액체-기체 삼상 접촉선에서 젖음성을 정량화하는 각도.","category":"Surface","example":"The contact angle has a very strong influence on the pool boiling CHF.","translation":"접촉각은 풀비등 CHF에 매우 강한 영향을 미친다.","collocations":["static contact angle","contact-angle measurement","wetting angle"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007) 691–706","sourceType":"논문 원문"},{"term":"wettability","pronunciation":"/ˌwetəˈbɪləti/","koreanPronunciation":"웨터빌리티","korean":"젖음성","meaning":"액체가 고체 표면에 퍼지고 접촉을 유지하려는 성질.","category":"Surface","example":"Improved wettability can enhance liquid contact with the heating surface.","translation":"향상된 젖음성은 가열면과 액체의 접촉을 개선할 수 있다.","collocations":["surface wettability","enhanced wettability","wetting behavior"],"paper":"CHF and surface literature","sourceType":"학습 예문"},{"term":"capillary wicking","pronunciation":"/ˈkæpɪleri ˈwɪkɪŋ/","koreanPronunciation":"캐필러리 위킹","korean":"모세관 위킹","meaning":"미세구조나 다공성 구조가 모세관력으로 액체를 끌어올리거나 공급하는 현상.","category":"Surface","example":"Capillary wicking can supply liquid to regions that tend to dry out.","translation":"모세관 위킹은 건조되기 쉬운 영역으로 액체를 공급할 수 있다.","collocations":["wicking performance","capillary force","wicking height"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007)","sourceType":"학습 예문"},{"term":"porosity","pronunciation":"/pəˈrɑːsəti/","koreanPronunciation":"퍼라서티","korean":"공극률","meaning":"재료 전체 체적 중 기공이 차지하는 체적 비율.","category":"Surface","example":"High porosity can increase liquid storage and transport within a coating.","translation":"높은 공극률은 코팅 내부의 액체 저장 및 수송을 증가시킬 수 있다.","collocations":["high porosity","porous layer","pore volume"],"paper":"Porous-coating literature","sourceType":"학습 예문"},{"term":"morphology","pronunciation":"/mɔːrˈfɑːlədʒi/","koreanPronunciation":"모폴러지","korean":"형상, 형태학","meaning":"표면 구조의 크기, 모양, 분포 및 연결성을 포괄하는 용어.","category":"Surface","example":"Boiling performance depends strongly on coating thickness and morphology.","translation":"비등 성능은 코팅 두께와 형상에 크게 좌우된다.","collocations":["surface morphology","coating morphology","morphological change"],"paper":"Surface-modified boiling literature","sourceType":"학습 예문"},{"term":"microstructure","pronunciation":"/ˈmaɪkroʊˌstrʌktʃər/","koreanPronunciation":"마이크로스트럭처","korean":"미세구조","meaning":"마이크로미터 규모에서 관찰되는 표면 또는 재료 구조.","category":"Surface","example":"Microstructures can provide additional cavities and capillary pathways.","translation":"미세구조는 추가 공동과 모세관 유로를 제공할 수 있다.","collocations":["surface microstructure","microstructured surface","micro-scale structure"],"paper":"Surface engineering literature","sourceType":"학습 예문"},{"term":"nanostructure","pronunciation":"/ˈnænoʊˌstrʌktʃər/","koreanPronunciation":"나노스트럭처","korean":"나노구조","meaning":"나노미터 규모의 표면 구조.","category":"Surface","example":"Nanostructures can modify wettability and interfacial transport.","translation":"나노구조는 젖음성과 계면 수송 특성을 변화시킬 수 있다.","collocations":["nanostructured surface","nano-scale structure","nanostructure density"],"paper":"Surface engineering literature","sourceType":"학습 예문"},{"term":"coating","pronunciation":"/ˈkoʊtɪŋ/","koreanPronunciation":"코팅","korean":"코팅, 피막","meaning":"기판 표면 위에 형성된 별도의 재료층.","category":"Surface","example":"The coating changes both surface geometry and interfacial properties.","translation":"코팅은 표면 형상과 계면 물성을 모두 변화시킨다.","collocations":["porous coating","surface coating","coating thickness"],"paper":"Surface modification literature","sourceType":"학습 예문"},{"term":"capillary-porous coating","pronunciation":"/ˈkæpɪleri ˈpɔːrəs ˈkoʊtɪŋ/","koreanPronunciation":"캐필러리 포러스 코팅","korean":"모세관-다공성 코팅","meaning":"모세관 액체 공급을 촉진하도록 설계된 다공성 표면층.","category":"Surface","example":"Capillary-porous coatings can strongly alter boiling heat transfer and crisis behavior.","translation":"모세관-다공성 코팅은 비등 열전달과 비등 위기 거동을 크게 변화시킬 수 있다.","collocations":["porous coating","capillary structure","coated heater"],"paper":"Surtaev et al., IJHMT 108 (2017)","sourceType":"학습 예문"},{"term":"nanoparticle deposition","pronunciation":"/ˈnænoʊˌpɑːrtɪkəl ˌdepəˈzɪʃən/","koreanPronunciation":"나노파티클 데퍼지션","korean":"나노입자 침착","meaning":"입자가 가열면에 부착되어 표면층을 형성하는 현상.","category":"Surface","example":"Nanoparticle deposition can modify roughness, contact angle, and wicking performance.","translation":"나노입자 침착은 거칠기, 접촉각 및 위킹 성능을 변화시킬 수 있다.","collocations":["particle deposition","deposited layer","surface coating"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007)","sourceType":"학습 예문"},{"term":"interfacial properties","pronunciation":"/ˌɪntərˈfeɪʃəl ˈprɑːpərtiz/","koreanPronunciation":"인터페이셜 프로퍼티즈","korean":"계면 물성","meaning":"고체-액체 또는 액체-기체 계면의 젖음, 표면에너지 등 관련 특성.","category":"Surface","example":"The coating can alter interfacial properties between the wire and surrounding liquid.","translation":"코팅은 와이어와 주변 액체 사이의 계면 물성을 변화시킬 수 있다.","collocations":["solid-liquid interface","surface energy","interfacial behavior"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007)","sourceType":"학습 예문"},{"term":"roughening","pronunciation":"/ˈrʌfənɪŋ/","koreanPronunciation":"러프닝","korean":"표면 거칠게 하기","meaning":"표면 요철을 증가시키는 처리 또는 그 결과.","category":"Surface","example":"Simple surface roughening may increase the number of active nucleation sites.","translation":"단순 표면 조면화는 활성 핵생성 지점 수를 증가시킬 수 있다.","collocations":["surface roughening","roughened surface","roughening effect"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007)","sourceType":"학습 예문"},{"term":"experimental apparatus","pronunciation":"/ɪkˌsperɪˈmentəl ˌæpəˈrætəs/","koreanPronunciation":"익스페리멘털 애퍼래터스","korean":"실험 장치","meaning":"실험에 사용되는 전체 장비와 구성 요소.","category":"Experiment","example":"A visual apparatus was constructed to observe pool boiling in liquid nitrogen.","translation":"액체질소 풀비등을 관찰하기 위한 가시화 장치를 구축하였다.","collocations":["experimental rig","test apparatus","experimental setup"],"paper":"Jin et al., Cryogenics 51 (2011) 516–520","sourceType":"논문 기반 예문"},{"term":"high-speed camera","pronunciation":"/ˌhaɪ ˈspiːd ˈkæmərə/","koreanPronunciation":"하이 스피드 캐머라","korean":"고속카메라","meaning":"기포 성장·이탈과 같은 빠른 현상을 시간 분해하여 촬영하는 카메라.","category":"Experiment","example":"A high-speed camera recorded the growth and departure of coalesced bubbles.","translation":"고속카메라로 합체 기포의 성장과 이탈을 기록하였다.","collocations":["high-speed imaging","frame rate","video recording"],"paper":"Jin et al., Cryogenics 51 (2011) 516–520","sourceType":"논문 기반 예문"},{"term":"image acquisition","pronunciation":"/ˈɪmɪdʒ ˌækwɪˈzɪʃən/","koreanPronunciation":"이미지 애퀴지션","korean":"영상 획득","meaning":"카메라 또는 센서로 이미지를 수집하고 저장하는 과정.","category":"Experiment","example":"The image acquisition system was synchronized with the electrical measurements.","translation":"영상 획득 시스템은 전기 측정과 동기화되었다.","collocations":["data acquisition","high-speed acquisition","acquisition system"],"paper":"Experimental methods","sourceType":"학습 예문"},{"term":"steady-state","pronunciation":"/ˌstedi ˈsteɪt/","koreanPronunciation":"스테디 스테이트","korean":"정상상태의","meaning":"시간에 따라 주요 상태량이 거의 변하지 않는 상태.","category":"Experiment","example":"The liquid nitrogen was left at low boiling conditions until thermal steady state was reached.","translation":"열적 정상상태에 도달할 때까지 액체질소를 저비등 조건에 두었다.","collocations":["steady-state condition","steady-state heating","thermal steady state"],"paper":"Cryogenic test-procedure literature","sourceType":"학습 예문"},{"term":"transient","pronunciation":"/ˈtrænziənt/","koreanPronunciation":"트랜지언트","korean":"과도상태의","meaning":"시간에 따라 물리량이 빠르게 변하는 비정상 상태.","category":"Experiment","example":"Transient heating can produce a boiling response different from steady-state heating.","translation":"과도 가열은 정상상태 가열과 다른 비등 응답을 유발할 수 있다.","collocations":["transient heating","transient response","transient CHF"],"paper":"Transient-boiling literature","sourceType":"학습 예문"},{"term":"stepwise heat release","pronunciation":"/ˈstepwaɪz hiːt rɪˈliːs/","koreanPronunciation":"스텝와이즈 히트 릴리스","korean":"단계적 열방출","meaning":"열입력을 단계적으로 증가시키는 가열 방식.","category":"Experiment","example":"Stepwise heat release was used to examine the transition process.","translation":"전이 과정을 조사하기 위해 단계적 열방출을 사용하였다.","collocations":["stepwise heating","heat step","power step"],"paper":"Surtaev et al., IJHMT 108 (2017)","sourceType":"학습 예문"},{"term":"heat pulse","pronunciation":"/hiːt pʌls/","koreanPronunciation":"히트 펄스","korean":"열펄스","meaning":"짧은 시간 동안 급격하게 인가되는 열입력.","category":"Experiment","example":"A heat pulse can trigger rapid vapor formation near the heater surface.","translation":"열펄스는 가열면 부근에서 급격한 증기 형성을 유발할 수 있다.","collocations":["power pulse","pulse heating","transient pulse"],"paper":"Transient-boiling literature","sourceType":"학습 예문"},{"term":"thermal conductivity","pronunciation":"/ˈθɜːrməl ˌkɑːndʌkˈtɪvəti/","koreanPronunciation":"써멀 컨덕티비티","korean":"열전도율","meaning":"온도구배에 의해 열이 전달되는 능력을 나타내는 물성.","category":"Heat Transfer","example":"The uncertainty of k is then considered as 5%.","translation":"열전도율 k의 불확도는 5%로 고려하였다.","collocations":["temperature-dependent conductivity","thermal property","k value"],"paper":"Cryogenic boiling experiment, uncertainty section","sourceType":"논문 원문"},{"term":"calibration","pronunciation":"/ˌkælɪˈbreɪʃən/","koreanPronunciation":"캘리브레이션","korean":"교정","meaning":"측정기 출력과 기준값 사이의 관계를 확립하는 과정.","category":"Experiment","example":"The thermocouples were calibrated in liquid nitrogen near 77 K.","translation":"열전대는 약 77 K의 액체질소에서 교정되었다.","collocations":["sensor calibration","calibration curve","calibration uncertainty"],"paper":"Experimental methods","sourceType":"학습 예문"},{"term":"uncertainty","pronunciation":"/ʌnˈsɜːrtənti/","koreanPronunciation":"언서턴티","korean":"불확도","meaning":"측정 또는 계산 결과의 신뢰 범위를 정량적으로 나타내는 값.","category":"Experiment","example":"Measurement uncertainty should be propagated through the heat-flux calculation.","translation":"측정 불확도는 열유속 계산 과정에 전파되어야 한다.","collocations":["measurement uncertainty","combined uncertainty","uncertainty analysis"],"paper":"Experimental methods","sourceType":"학습 예문"},{"term":"systematic error","pronunciation":"/ˌsɪstəˈmætɪk ˈerər/","koreanPronunciation":"시스터매틱 에러","korean":"계통오차","meaning":"반복 측정에서 일정한 방향으로 나타나는 편향 오차.","category":"Experiment","example":"Calibration near the operating temperature helps reduce systematic error.","translation":"운전 온도 근처에서의 교정은 계통오차 감소에 도움이 된다.","collocations":["bias error","systematic uncertainty","measurement bias"],"paper":"Measurement science","sourceType":"학습 예문"},{"term":"measurement accuracy","pronunciation":"/ˈmeʒərmənt ˈækjərəsi/","koreanPronunciation":"메저먼트 애큐러시","korean":"측정 정확도","meaning":"측정값이 참값에 얼마나 가까운지를 나타내는 성능.","category":"Experiment","example":"The power supply accuracy was used as an independent check of the calculated heat flux.","translation":"전원공급기의 정확도는 계산된 열유속의 독립 검증에 사용되었다.","collocations":["instrument accuracy","accuracy specification","improve accuracy"],"paper":"Experimental methods","sourceType":"학습 예문"},{"term":"repeatability","pronunciation":"/rɪˌpiːtəˈbɪləti/","koreanPronunciation":"리피터빌리티","korean":"반복성","meaning":"동일한 조건에서 반복 측정한 결과가 서로 얼마나 잘 일치하는지를 나타내는 특성.","category":"Experiment","example":"Repeatability was evaluated from repeated boiling runs under identical conditions.","translation":"반복성은 동일 조건의 반복 비등 실험으로 평가하였다.","collocations":["repeatable result","run-to-run variation","repeatability test"],"paper":"Experimental methods","sourceType":"학습 예문"},{"term":"investigate","pronunciation":"/ɪnˈvestɪɡeɪt/","koreanPronunciation":"인베스티게이트","korean":"조사하다, 규명하다","meaning":"현상이나 변수의 영향을 체계적으로 연구하다.","category":"Academic English","example":"The present study investigates the effect of surface condition on boiling behavior.","translation":"본 연구는 표면 상태가 비등 거동에 미치는 영향을 조사한다.","collocations":["investigate the effect of","investigate experimentally"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"evaluate","pronunciation":"/ɪˈvæljueɪt/","koreanPronunciation":"이밸류에이트","korean":"평가하다","meaning":"성능, 정확도, 효과 등을 정량적 또는 정성적으로 판단하다.","category":"Academic English","example":"The uncertainty was evaluated for each measured quantity.","translation":"각 측정량에 대해 불확도를 평가하였다.","collocations":["evaluate performance","evaluate uncertainty"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"determine","pronunciation":"/dɪˈtɜːrmɪn/","koreanPronunciation":"디터민","korean":"결정하다, 구하다","meaning":"측정이나 계산으로 특정 값을 정하거나 밝혀내다.","category":"Academic English","example":"The CHF was determined from the maximum heat flux before the temperature excursion.","translation":"CHF는 온도 급상승 전 최대 열유속으로 결정하였다.","collocations":["determine the value","experimentally determine"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"obtain","pronunciation":"/əbˈteɪn/","koreanPronunciation":"업테인","korean":"얻다","meaning":"실험, 계산, 문헌으로 결과나 데이터를 획득하다.","category":"Academic English","example":"The boiling curve was obtained from the measured voltage and current.","translation":"비등곡선은 측정된 전압과 전류로부터 얻었다.","collocations":["obtain data","obtain a value","results obtained"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"measure","pronunciation":"/ˈmeʒər/","koreanPronunciation":"메저","korean":"측정하다","meaning":"실험 계측기로 물리량을 정량화하다.","category":"Academic English","example":"The surface temperature was measured during each heating step.","translation":"각 가열 단계에서 표면 온도를 측정하였다.","collocations":["measure directly","measured value"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"calculate","pronunciation":"/ˈkælkjuleɪt/","koreanPronunciation":"캘큘레이트","korean":"계산하다","meaning":"식이나 모델을 이용하여 값을 산출하다.","category":"Academic English","example":"Heat flux was calculated from the electrical power and heater area.","translation":"열유속은 전기 입력과 가열면적으로부터 계산하였다.","collocations":["calculate from","calculated value"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"estimate","pronunciation":"/ˈestɪmeɪt/","koreanPronunciation":"에스티메이트","korean":"추정하다","meaning":"직접 측정하기 어려운 값을 데이터나 모델로 근사적으로 구하다.","category":"Academic English","example":"The heat loss was estimated from an energy balance.","translation":"열손실은 에너지 수지로 추정하였다.","collocations":["estimate uncertainty","roughly estimate"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"analyze","pronunciation":"/ˈænəlaɪz/","koreanPronunciation":"애널라이즈","korean":"분석하다","meaning":"데이터나 현상을 구성 요소와 관계로 나누어 해석하다.","category":"Academic English","example":"The bubble images were analyzed frame by frame.","translation":"기포 영상은 프레임별로 분석하였다.","collocations":["analyze data","analyze the effect"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"compare","pronunciation":"/kəmˈper/","koreanPronunciation":"컴페어","korean":"비교하다","meaning":"두 조건이나 모델의 차이와 유사성을 검토하다.","category":"Academic English","example":"The experimental data were compared with existing correlations.","translation":"실험 데이터는 기존 상관식과 비교하였다.","collocations":["compare with","as compared to"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"indicate","pronunciation":"/ˈɪndɪkeɪt/","koreanPronunciation":"인디케이트","korean":"나타내다, 시사하다","meaning":"결과가 특정 해석이나 경향을 지지함을 표현하다.","category":"Academic English","example":"The results indicate that wettability is an important parameter.","translation":"결과는 젖음성이 중요한 변수임을 시사한다.","collocations":["results indicate","indicate a trend"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"reveal","pronunciation":"/rɪˈviːl/","koreanPronunciation":"리빌","korean":"밝히다, 드러내다","meaning":"관찰이나 분석 결과 새로운 사실이 나타남을 표현하다.","category":"Academic English","example":"SEM images revealed substantial changes in surface morphology.","translation":"SEM 이미지는 표면 형상의 상당한 변화를 보여주었다.","collocations":["reveal that","analysis revealed"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"demonstrate","pronunciation":"/ˈdemənstreɪt/","koreanPronunciation":"데먼스트레이트","korean":"입증하다, 보여주다","meaning":"결과가 주장이나 메커니즘을 뚜렷하게 뒷받침함을 표현하다.","category":"Academic English","example":"The experiment demonstrates the importance of surface condition.","translation":"실험은 표면 상태의 중요성을 보여준다.","collocations":["demonstrate that","clearly demonstrate"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"exhibit","pronunciation":"/ɪɡˈzɪbɪt/","koreanPronunciation":"이그지빗","korean":"나타내다, 보이다","meaning":"재료나 데이터가 특정 성질 또는 경향을 보일 때 자주 쓰는 동사.","category":"Academic English","example":"The modified heater exhibited a larger heat transfer coefficient.","translation":"개질된 가열기는 더 큰 열전달계수를 나타냈다.","collocations":["exhibit a trend","exhibit higher values"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"observe","pronunciation":"/əbˈzɜːrv/","koreanPronunciation":"업저브","korean":"관찰하다","meaning":"실험 중 현상이나 변화를 직접 확인하다.","category":"Academic English","example":"A rapid increase in resistance was observed near CHF.","translation":"CHF 부근에서 저항의 급격한 증가가 관찰되었다.","collocations":["was observed","observe a change"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"occur","pronunciation":"/əˈkɜːr/","koreanPronunciation":"어커","korean":"발생하다","meaning":"현상이나 사건이 일어남을 나타내다.","category":"Academic English","example":"Bubble coalescence occurs more frequently at high heat flux.","translation":"기포 합체는 고열유속에서 더 자주 발생한다.","collocations":["occur at","occur during"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"enhance","pronunciation":"/ɪnˈhæns/","koreanPronunciation":"인핸스","korean":"향상시키다","meaning":"열전달, CHF, 젖음성 등의 성능을 높이다.","category":"Academic English","example":"The CHF of the nanofluids was significantly higher than that of pure water.","translation":"나노유체의 CHF는 순수 물보다 유의하게 높았다.","collocations":["enhance CHF","heat transfer enhancement"],"paper":"Kim et al., Int. J. Multiphase Flow 33 (2007)","sourceType":"논문 기반 예문"},{"term":"affect","pronunciation":"/əˈfekt/","koreanPronunciation":"어펙트","korean":"영향을 미치다","meaning":"한 변수가 다른 변수나 현상에 영향을 주는 것을 표현하다.","category":"Academic English","example":"Surface condition affects both nucleation and liquid supply.","translation":"표면 상태는 핵생성과 액체 공급 모두에 영향을 미친다.","collocations":["affect strongly","affect the behavior"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"influence","pronunciation":"/ˈɪnfluəns/","koreanPronunciation":"인플루언스","korean":"영향을 미치다","meaning":"affect와 유사하나 명사로도 매우 자주 쓰인다.","category":"Academic English","example":"Pressure can influence bubble dynamics and saturation temperature.","translation":"압력은 기포 거동과 포화온도에 영향을 줄 수 있다.","collocations":["influence on","strong influence"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"depend on","pronunciation":"/dɪˈpend ɑːn/","koreanPronunciation":"디펜드 온","korean":"~에 달려 있다","meaning":"결과가 특정 변수의 함수임을 표현하다.","category":"Academic English","example":"Boiling performance depends on surface morphology and operating pressure.","translation":"비등 성능은 표면 형상과 운전 압력에 달려 있다.","collocations":["strongly depend on","depend primarily on"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"result in","pronunciation":"/rɪˈzʌlt ɪn/","koreanPronunciation":"리절트 인","korean":"~을 초래하다","meaning":"앞의 원인이 뒤의 결과를 발생시키는 인과관계를 나타내다.","category":"Academic English","example":"Local dryout can result in a sharp increase in surface temperature.","translation":"국부 건조는 표면 온도의 급격한 증가를 초래할 수 있다.","collocations":["result in an increase","result in failure"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"lead to","pronunciation":"/liːd tuː/","koreanPronunciation":"리드 투","korean":"~로 이어지다","meaning":"원인-결과 관계를 설명하는 매우 빈번한 표현.","category":"Academic English","example":"Improved liquid supply can lead to higher CHF.","translation":"향상된 액체 공급은 더 높은 CHF로 이어질 수 있다.","collocations":["lead to enhancement","lead to a decrease"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"contribute to","pronunciation":"/kənˈtrɪbjuːt tuː/","koreanPronunciation":"컨트리뷰트 투","korean":"~에 기여하다","meaning":"하나의 요인이 전체 현상의 일부 원인임을 표현하다.","category":"Academic English","example":"Capillary wicking may contribute to CHF enhancement.","translation":"모세관 위킹은 CHF 향상에 기여할 수 있다.","collocations":["contribute significantly to","contributing factor"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"be attributed to","pronunciation":"/bi əˈtrɪbjuːtɪd tuː/","koreanPronunciation":"비 어트리뷰티드 투","korean":"~에 기인하다","meaning":"관찰된 결과의 원인을 설명할 때 매우 자주 쓰는 표현.","category":"Academic English","example":"The CHF enhancement was attributed to improved surface wettability.","translation":"CHF 향상은 개선된 표면 젖음성에 기인한 것으로 해석되었다.","collocations":["mainly attributed to","partly attributed to"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"account for","pronunciation":"/əˈkaʊnt fɔːr/","koreanPronunciation":"어카운트 포","korean":"고려하다, 설명하다","meaning":"모델이 특정 효과를 포함하거나 데이터의 원인을 설명함을 나타낸다.","category":"Academic English","example":"The correlation accounts for the effects of pressure and surface orientation.","translation":"상관식은 압력과 표면 방향의 영향을 고려한다.","collocations":["account for the effect of","account for variation"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"consist of","pronunciation":"/kənˈsɪst əv/","koreanPronunciation":"컨시스트 오브","korean":"~로 구성되다","meaning":"실험장치나 시스템의 구성요소를 설명할 때 자주 쓰인다.","category":"Academic English","example":"The experimental rig consists of a vessel, test section, and data-acquisition system.","translation":"실험 장치는 용기, 시험부 및 데이터 획득 시스템으로 구성된다.","collocations":["mainly consists of","consist of three parts"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"be based on","pronunciation":"/bi beɪst ɑːn/","koreanPronunciation":"비 베이스트 온","korean":"~에 근거하다","meaning":"모델·계산·결론의 근거를 밝힐 때 사용한다.","category":"Academic English","example":"The correlation is based on experimental data.","translation":"상관식은 실험 데이터에 기반한다.","collocations":["based on data","based on the assumption"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"be related to","pronunciation":"/bi rɪˈleɪtɪd tuː/","koreanPronunciation":"비 릴레이티드 투","korean":"~와 관련되다","meaning":"변수나 현상 사이의 관련성을 표현한다.","category":"Academic English","example":"The change in CHF is closely related to surface wettability.","translation":"CHF 변화는 표면 젖음성과 밀접하게 관련된다.","collocations":["closely related to","directly related to"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"respectively","pronunciation":"/rɪˈspektɪvli/","koreanPronunciation":"리스펙티블리","korean":"각각","meaning":"앞서 열거한 항목과 뒤의 값을 순서대로 대응시킬 때 쓴다.","category":"Academic English","example":"The uncertainties in heat flux and temperature were 5% and 0.2 K, respectively.","translation":"열유속과 온도의 불확도는 각각 5%와 0.2 K였다.","collocations":["A and B, respectively"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"significantly","pronunciation":"/sɪɡˈnɪfɪkəntli/","koreanPronunciation":"시그니피컨틀리","korean":"유의하게, 현저하게","meaning":"차이나 변화가 충분히 크거나 통계적으로 의미 있음을 표현한다.","category":"Academic English","example":"The modified surface significantly increased the heat transfer coefficient.","translation":"개질 표면은 열전달계수를 현저하게 증가시켰다.","collocations":["significantly higher","significantly affect"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"relatively","pronunciation":"/ˈrelətɪvli/","koreanPronunciation":"렐러티블리","korean":"상대적으로, 비교적","meaning":"다른 경우와 비교하여 정도가 작거나 큼을 나타낸다.","category":"Academic English","example":"Research on cryogenic liquids is relatively limited.","translation":"극저온 액체에 대한 연구는 상대적으로 제한적이다.","collocations":["relatively low","relatively small"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"approximately","pronunciation":"/əˈprɑːksɪmətli/","koreanPronunciation":"어프락시멋리","korean":"약, 대략","meaning":"수치가 정확한 값이 아니라 근사값임을 나타낸다.","category":"Academic English","example":"The propagation velocity was approximately 5 mm/s.","translation":"전파 속도는 약 5 mm/s였다.","collocations":["approximately equal to","approximately 5%"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"however","pronunciation":"/haʊˈevər/","koreanPronunciation":"하우에버","korean":"그러나","meaning":"앞 문장과 대조되는 내용을 연결하는 대표적인 학술 연결어.","category":"Academic English","example":"The roughness increased; however, the CHF did not change proportionally.","translation":"거칠기는 증가했지만 CHF는 비례하여 변하지 않았다.","collocations":["however,","however, this does not"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"therefore","pronunciation":"/ˈðerfɔːr/","koreanPronunciation":"데어포어","korean":"따라서","meaning":"앞의 근거에서 논리적 결론을 이끌어낼 때 사용한다.","category":"Academic English","example":"The liquid supply improved; therefore, dryout was delayed.","translation":"액체 공급이 개선되었으므로 건조가 지연되었다.","collocations":["therefore,","can therefore be"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"whereas","pronunciation":"/werˈæz/","koreanPronunciation":"웨어애즈","korean":"반면에","meaning":"두 조건이나 결과를 직접 대조할 때 사용한다.","category":"Academic English","example":"The bare surface showed early dryout, whereas the modified surface remained wetted.","translation":"베어 표면은 조기 건조를 보인 반면 개질 표면은 젖은 상태를 유지했다.","collocations":["whereas the","A whereas B"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"in terms of","pronunciation":"/ɪn tɜːrmz əv/","koreanPronunciation":"인 텀즈 오브","korean":"~의 관점에서, ~에 있어서","meaning":"특정 평가 기준이나 변수에 초점을 맞출 때 사용한다.","category":"Academic English","example":"The surfaces were compared in terms of CHF and heat transfer coefficient.","translation":"표면들은 CHF와 열전달계수 관점에서 비교되었다.","collocations":["in terms of performance","in terms of"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"as compared to","pronunciation":"/æz kəmˈperd tuː/","koreanPronunciation":"애즈 컴페어드 투","korean":"~와 비교하여","meaning":"기준 조건 대비 차이를 서술할 때 자주 사용한다.","category":"Academic English","example":"The modified heater showed a higher HTC as compared to the smooth heater.","translation":"개질 가열기는 평활 가열기와 비교해 더 높은 HTC를 보였다.","collocations":["as compared with","compared to"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"due to","pronunciation":"/duː tuː/","koreanPronunciation":"듀 투","korean":"~ 때문에","meaning":"명사구와 함께 원인을 제시하는 대표 표현.","category":"Academic English","example":"The high error is due to the large temperature drop in the test element.","translation":"높은 오차는 시험부의 큰 온도 강하 때문이다.","collocations":["due to the effect of","mainly due to"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"according to","pronunciation":"/əˈkɔːrdɪŋ tuː/","koreanPronunciation":"어코딩 투","korean":"~에 따르면","meaning":"문헌, 모델, 기준에 근거하여 진술할 때 사용한다.","category":"Academic English","example":"According to the correlation, CHF increases with decreasing contact angle.","translation":"상관식에 따르면 접촉각이 감소할수록 CHF가 증가한다.","collocations":["according to Eq.","according to previous studies"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"in order to","pronunciation":"/ɪn ˈɔːrdər tuː/","koreanPronunciation":"인 오더 투","korean":"~하기 위해","meaning":"실험 절차나 연구 목적을 설명하는 빈번한 표현.","category":"Academic English","example":"In order to reduce heat leak, the vessel was vacuum insulated.","translation":"열침입을 줄이기 위해 용기를 진공 단열하였다.","collocations":["in order to evaluate","in order to reduce"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"agree well with","pronunciation":"/əˈɡriː wel wɪð/","koreanPronunciation":"어그리 웰 위드","korean":"~와 잘 일치하다","meaning":"실험 결과와 상관식·문헌값의 일치도를 표현한다.","category":"Academic English","example":"The selected correlation showed good agreement with the liquid-nitrogen data.","translation":"선정한 상관식은 액체질소 데이터와 잘 일치하였다.","collocations":["good agreement","agree reasonably well with"],"paper":"Jin et al., Cryogenics 51 (2011)","sourceType":"논문 기반 예문"},{"term":"be consistent with","pronunciation":"/bi kənˈsɪstənt wɪð/","koreanPronunciation":"비 컨시스턴트 위드","korean":"~와 일치하다","meaning":"결과가 기존 연구나 예상 경향과 모순되지 않음을 표현한다.","category":"Academic English","example":"This trend is consistent with previous boiling studies.","translation":"이 경향은 기존 비등 연구와 일치한다.","collocations":["consistent with previous studies","consistent result"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"be independent of","pronunciation":"/bi ˌɪndɪˈpendənt əv/","koreanPronunciation":"비 인디펜던트 오브","korean":"~와 무관하다","meaning":"한 변수의 변화가 다른 변수에 영향을 주지 않음을 표현한다.","category":"Academic English","example":"The detachment frequency was nearly independent of pressure in this range.","translation":"이 범위에서 이탈 빈도는 압력에 거의 무관했다.","collocations":["independent of heat flux","largely independent of"],"paper":"General academic writing","sourceType":"학습 예문"},{"term":"parameter","pronunciation":"/pəˈræmɪtər/","koreanPronunciation":"퍼래미터","korean":"매개변수, 변수","meaning":"모델이나 실험에서 영향을 평가하는 물리량.","category":"Academic English","example":"Contact angle is an important parameter for CHF prediction.","translation":"접촉각은 CHF 예측에서 중요한 매개변수이다.","collocations":["key parameter","model parameter","operating parameter"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"correlation","pronunciation":"/ˌkɔːrəˈleɪʃən/","koreanPronunciation":"코럴레이션","korean":"상관식, 상관관계","meaning":"실험 변수 사이의 관계를 경험식 또는 수식으로 나타낸 것.","category":"Academic English","example":"The experimental data were compared with an empirical correlation.","translation":"실험 데이터는 경험 상관식과 비교하였다.","collocations":["empirical correlation","CHF correlation","correlation equation"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"empirical","pronunciation":"/ɪmˈpɪrɪkəl/","koreanPronunciation":"임피리컬","korean":"경험적인","meaning":"이론만이 아니라 관측·실험 데이터에 기반한 것을 의미한다.","category":"Academic English","example":"An empirical correlation was developed from the measured data.","translation":"측정 데이터로부터 경험 상관식을 개발하였다.","collocations":["empirical data","empirical model","semi-empirical"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"applicability","pronunciation":"/əˌplɪkəˈbɪləti/","koreanPronunciation":"어플리커빌리티","korean":"적용 가능성","meaning":"모델이나 상관식이 특정 조건에 사용할 수 있는 정도.","category":"Academic English","example":"The applicability of the correlation to liquid nitrogen was examined.","translation":"액체질소에 대한 상관식의 적용 가능성을 검토하였다.","collocations":["check applicability","range of applicability"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"characterize","pronunciation":"/ˈkærəktəraɪz/","koreanPronunciation":"캐릭터라이즈","korean":"특성화하다","meaning":"표면이나 재료의 물성을 측정하여 정량적으로 설명하다.","category":"Academic English","example":"The modified surface was characterized by roughness and contact angle.","translation":"개질 표면은 거칠기와 접촉각으로 특성화하였다.","collocations":["surface characterization","characterize the sample"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"quantify","pronunciation":"/ˈkwɑːntɪfaɪ/","koreanPronunciation":"퀀티파이","korean":"정량화하다","meaning":"관찰된 현상이나 차이를 수치로 나타내다.","category":"Academic English","example":"Surface roughness was used to quantify the structural change.","translation":"구조 변화를 정량화하기 위해 표면 거칠기를 사용하였다.","collocations":["quantify the effect","quantitative analysis"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"configuration","pronunciation":"/kənˌfɪɡjəˈreɪʃən/","koreanPronunciation":"컨피규레이션","korean":"구성, 형상","meaning":"장치 또는 표면 구조의 배열과 배치를 의미한다.","category":"Academic English","example":"The heater configuration was kept identical for all tests.","translation":"모든 실험에서 가열기 구성을 동일하게 유지하였다.","collocations":["experimental configuration","surface configuration"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"available","pronunciation":"/əˈveɪləbəl/","koreanPronunciation":"어베일러블","korean":"이용 가능한, 기존의","meaning":"논문에서 기존 데이터·상관식·문헌을 가리킬 때 자주 쓰인다.","category":"Academic English","example":"Available correlations were compared with the present experimental data.","translation":"기존 상관식들을 본 실험 데이터와 비교하였다.","collocations":["available data","available literature","available correlation"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"various","pronunciation":"/ˈveriəs/","koreanPronunciation":"베리어스","korean":"다양한","meaning":"여러 종류나 조건을 묶어 표현할 때 매우 자주 쓰인다.","category":"Academic English","example":"Various surface conditions were tested under the same pressure.","translation":"다양한 표면 조건을 동일 압력에서 시험하였다.","collocations":["various conditions","various methods","various parameters"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"subsequent","pronunciation":"/ˈsʌbsɪkwənt/","koreanPronunciation":"섭시퀀트","korean":"후속의, 이후의","meaning":"어떤 실험이나 사건 뒤에 이어지는 단계를 나타낸다.","category":"Academic English","example":"Subsequent SEM observation revealed changes in the wire surface.","translation":"후속 SEM 관찰에서 와이어 표면 변화가 확인되었다.","collocations":["subsequent analysis","subsequent experiment","subsequent to"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"surrounding","pronunciation":"/səˈraʊndɪŋ/","koreanPronunciation":"서라운딩","korean":"주변의","meaning":"가열면 주변 액체·환경을 서술할 때 자주 쓰인다.","category":"Academic English","example":"The interfacial properties depend on the surrounding liquid.","translation":"계면 물성은 주변 액체에 따라 달라진다.","collocations":["surrounding liquid","surrounding environment"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"corresponding","pronunciation":"/ˌkɔːrəˈspɑːndɪŋ/","koreanPronunciation":"코러스판딩","korean":"해당하는, 대응하는","meaning":"특정 조건과 연결된 값 또는 시편을 지칭한다.","category":"Academic English","example":"The corresponding heat flux was calculated for each voltage step.","translation":"각 전압 단계에 해당하는 열유속을 계산하였다.","collocations":["corresponding value","corresponding condition"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"increase","pronunciation":"/ɪnˈkriːs/","koreanPronunciation":"인크리스","korean":"증가하다","meaning":"논문 그래프 해석에서 가장 빈번한 변화 동사 중 하나.","category":"Academic English","example":"CHF increased with improved surface wettability.","translation":"표면 젖음성이 향상됨에 따라 CHF가 증가하였다.","collocations":["increase with","increase significantly","increase from A to B"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"decrease","pronunciation":"/dɪˈkriːs/","koreanPronunciation":"디크리스","korean":"감소하다","meaning":"논문 그래프 해석에서 매우 빈번한 변화 동사.","category":"Academic English","example":"The detachment frequency decreased with increasing heat flux.","translation":"열유속 증가에 따라 이탈 빈도가 감소하였다.","collocations":["decrease with","decrease gradually","decrease sharply"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"remain","pronunciation":"/rɪˈmeɪn/","koreanPronunciation":"리메인","korean":"유지되다, 남아 있다","meaning":"값이나 상태가 거의 변하지 않음을 표현한다.","category":"Academic English","example":"The detachment frequency remained nearly constant over the tested range.","translation":"시험 범위에서 이탈 빈도는 거의 일정하게 유지되었다.","collocations":["remain constant","remain unchanged","remain stable"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"approximately equal to","pronunciation":"/əˈprɑːksɪmətli ˈiːkwəl tuː/","koreanPronunciation":"어프락시멋리 이퀄 투","korean":"~와 거의 같다","meaning":"두 값이 근사적으로 같음을 표현한다.","category":"Academic English","example":"The bubble period was approximately equal to the macrolayer evaporation period.","translation":"기포 주기는 매크로층 증발 주기와 거의 같았다.","collocations":["approximately equal","nearly equal to"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"under atmospheric pressure","pronunciation":"/ˈʌndər ˌætməsˈferɪk ˈpreʃər/","koreanPronunciation":"언더 애트머스페릭 프레셔","korean":"대기압 조건에서","meaning":"실험 압력 조건을 서술하는 전형적인 표현.","category":"Experiment","example":"The boiling tests were conducted under atmospheric pressure.","translation":"비등 실험은 대기압 조건에서 수행하였다.","collocations":["at atmospheric pressure","ambient pressure"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"prior to","pronunciation":"/ˈpraɪər tuː/","koreanPronunciation":"프라이어 투","korean":"~에 앞서","meaning":"실험 절차에서 before보다 격식 있게 쓰이는 표현.","category":"Academic English","example":"The wire was cleaned prior to each boiling test.","translation":"각 비등 실험에 앞서 와이어를 세척하였다.","collocations":["prior to measurement","prior to testing"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"subsequent to","pronunciation":"/ˈsʌbsɪkwənt tuː/","koreanPronunciation":"섭시퀀트 투","korean":"~ 이후에","meaning":"after보다 격식 있게 후속 시점을 나타낸다.","category":"Academic English","example":"SEM observation was performed subsequent to the CHF experiment.","translation":"CHF 실험 이후 SEM 관찰을 수행하였다.","collocations":["subsequent to the test"],"paper":"General academic / boiling literature","sourceType":"학습 예문"},{"term":"influence on","pronunciation":"/ˈɪnfluəns ɑːn/","koreanPronunciation":"인플루언스 온","korean":"~에 대한 영향","meaning":"논문에서 effect on과 함께 매우 자주 쓰이는 명사형 표현.","category":"Academic English","example":"Surface wettability has a strong influence on pool boiling CHF.","translation":"표면 젖음성은 풀비등 CHF에 강한 영향을 미친다.","collocations":["strong influence on","influence on CHF"],"paper":"General academic / boiling literature","sourceType":"학습 예문"}];
